// Follows the site's rel="next" link until the last page, so the page count is never hard-coded.
const START_URL = 'https://webscraper.io/test-sites/e-commerce/static/computers/laptops';
const MAX_PAGES = 100;
const PAUSE_MS = 500;

const pages = [];
const visited = new Set();
let url = START_URL;

while (url) {
  if (visited.has(url)) {
    throw new Error(`Sayfalama döngüsü tespit edildi: ${url}`);
  }
  if (pages.length >= MAX_PAGES) {
    throw new Error(`Sayfa sınırı (${MAX_PAGES}) aşıldı; tarama eksik kabul edildi.`);
  }
  visited.add(url);

  let response;
  try {
    response = await this.helpers.httpRequest({
      method: 'GET',
      url,
      timeout: 20000,
      returnFullResponse: true,
      headers: { 'User-Agent': 'n8n-laptop-price-monitor/1.0' },
    });
  } catch (error) {
    throw new Error(`Sayfa açılamadı (${url}): ${error.message}`);
  }

  const html = typeof response.body === 'string' ? response.body : '';
  if (!html.trim()) {
    throw new Error(`Sayfa boş döndü: ${url}`);
  }
  pages.push({ json: { page_number: pages.length + 1, page_url: url, html } });

  const nextTag = html.match(/<a\b[^>]*\brel="next"[^>]*>/i);
  const nextHref = nextTag ? nextTag[0].match(/\bhref="([^"]+)"/i) : null;
  url = nextHref ? new URL(nextHref[1].replace(/&amp;/g, '&'), url).href : null;

  if (url && PAUSE_MS > 0) {
    await new Promise((resolve) => setTimeout(resolve, PAUSE_MS));
  }
}

return pages;

// Extracts name, numeric price, review count and absolute link from every product card.
// Any missing field, empty page or count mismatch fails the run instead of storing a partial scrape.
const decode = (value) => value
  .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ').trim();

const scrapedAt = new Date().toISOString();
const products = new Map();
let declaredTotal = null;

for (const { json: page } of $input.all()) {
  const countMatch = page.html.match(/class="item-count">\s*(\d+)\s*items/i);
  if (countMatch) declaredTotal = Number(countMatch[1]);

  const cards = page.html.split('itemtype="https://schema.org/Product"').slice(1);
  if (cards.length === 0) {
    throw new Error(`Sayfada ürün bulunamadı: ${page.page_url}`);
  }

  for (const card of cards) {
    const titleTag = (card.match(/<a\b[^>]*class="title"[^>]*>/i) || [])[0] || '';
    const href = (titleTag.match(/\bhref="([^"]+)"/i) || [])[1];
    const name = (titleTag.match(/\btitle="([^"]*)"/i) || [])[1];
    const priceText = ((card.match(/itemprop="price"[^>]*>([^<]*)</i) || [])[1] || '').trim();
    const reviewText = (card.match(/itemprop="reviewCount"[^>]*>\s*(\d+)\s*</i) || [])[1];

    if (!href || !name || !/^\$[\d,]+(\.\d{1,2})?$/.test(priceText) || reviewText === undefined) {
      throw new Error(`Eksik veya beklenmeyen ürün verisi: ${page.page_url}`);
    }

    const price = Number(priceText.replace(/[$,]/g, ''));
    const productUrl = new URL(decode(href), page.page_url).href;
    if (!products.has(productUrl)) {
      products.set(productUrl, {
        scraped_at: scrapedAt,
        name: decode(name),
        price,
        price_cents: Math.round(price * 100),
        review_count: Number(reviewText),
        product_url: productUrl,
      });
    }
  }
}

if (products.size === 0) {
  throw new Error('Hiç ürün toplanamadı.');
}
if (declaredTotal !== null && products.size !== declaredTotal) {
  throw new Error(`Site ${declaredTotal} ürün bildiriyor, ${products.size} benzersiz ürün toplandı; tarama eksik.`);
}

return [...products.values()].map((product) => ({ json: product }));

// Compares this run with latest_prices, keyed by product URL.
// Cents are compared as integers so sheet locale or float rounding cannot fake a change.
const toCents = (value) => {
  const digits = String(value ?? '').replace(/[^0-9-]/g, '');
  return digits === '' ? null : Number(digits);
};

const previous = new Map();
for (const { json: row } of $input.all()) {
  const url = String(row.product_url ?? '').trim();
  const cents = toCents(row.price_cents);
  if (url && Number.isInteger(cents)) previous.set(url, cents);
}
const isFirstRun = previous.size === 0;

return $('Parse Products').all().map(({ json: product }) => {
  const oldCents = previous.has(product.product_url) ? previous.get(product.product_url) : null;
  let changeType = 'unchanged';
  if (oldCents === null) changeType = isFirstRun ? 'baseline' : 'new';
  else if (product.price_cents > oldCents) changeType = 'price_up';
  else if (product.price_cents < oldCents) changeType = 'price_down';

  return {
    json: {
      ...product,
      previous_price: oldCents === null ? null : oldCents / 100,
      change_type: changeType,
    },
  };
});

// Builds a single Telegram message for the whole run instead of one alert per product.
const MAX_LINES = 30;
const money = (value) => `$${Number(value).toFixed(2)}`;
const products = $('Detect Changes').all().map((item) => item.json);
const byType = (type) => products.filter((product) => product.change_type === type);
const runTime = new Date(products[0].scraped_at).toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });

if (byType('baseline').length === products.length) {
  return [{ json: {
    notify: true,
    message: `Laptop fiyat takibi başlatıldı (${runTime}).\n${products.length} ürün başlangıç kaydı olarak tabloya yazıldı. Sonraki çalışmalarda yalnızca yeni ürünler ve fiyat değişiklikleri bildirilecek.`,
  } }];
}

const lines = [
  ...byType('new').map((p) => `🆕 Yeni: ${p.name} - ${money(p.price)}\n${p.product_url}`),
  ...byType('price_down').map((p) => `📉 Düştü: ${p.name} ${money(p.previous_price)} → ${money(p.price)}\n${p.product_url}`),
  ...byType('price_up').map((p) => `📈 Arttı: ${p.name} ${money(p.previous_price)} → ${money(p.price)}\n${p.product_url}`),
];

if (lines.length === 0) {
  return [{ json: { notify: false, message: '' } }];
}

const shown = lines.slice(0, MAX_LINES);
if (lines.length > MAX_LINES) shown.push(`… ve ${lines.length - MAX_LINES} değişiklik daha (price_history sayfasına bakın).`);

return [{ json: {
  notify: true,
  message: [
    `Laptop fiyat takibi - ${runTime}`,
    `Taranan ürün: ${products.length} | Yeni: ${byType('new').length} | Düşen: ${byType('price_down').length} | Artan: ${byType('price_up').length}`,
    '',
    ...shown,
  ].join('\n'),
} }];

// Collapses any number of failed items into one alert so the error branch never floods the chat.
const first = $input.first().json;
const detail = first.error?.message ?? first.error ?? first.message ?? 'Ayrıntı yok';
const step = $prevNode.name ?? 'bilinmeyen adım';
const time = new Date().toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });

return [{ json: {
  step,
  message: `⚠️ Laptop fiyat takibi BAŞARISIZ (${time})\nAdım: ${step}\nHata: ${String(detail).slice(0, 500)}\nBu çalışma karşılaştırma referansı olarak kaydedilmedi. Execution: ${$execution.id}`,
} }];
